import{_ as t,o,c as e,a3 as r}from"./chunks/framework.Dj4Lt7vj.js";const u=JSON.parse('{"title":"对话测试","description":"","frontmatter":{"title":"对话测试"},"headers":[],"relativePath":"solution/test.md","filePath":"solution/test.md","lastUpdated":1787949005000}'),l={name:"solution/test.md"};function i(s,a,n,d,c,h){return o(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="对话测试" tabindex="-1">对话测试 <a class="header-anchor" href="#对话测试" aria-label="Permalink to &quot;对话测试&quot;">​</a></h1><p>上线前先自己当一回顾客。对话测试用真实的方案配置模拟接待，不经过任何电商平台，放心随便问。</p><p>入口：方案编辑器 → 「对话测试」。网页工作台「对话测试」标签页是同一个能力。</p><h2 id="怎么测" tabindex="-1">怎么测 <a class="header-anchor" href="#怎么测" aria-label="Permalink to &quot;怎么测&quot;">​</a></h2><ol><li>打开对话测试，确认测的是目标方案。</li><li>用顾客的真实问法提问——别用你自己的说法，翻翻历史聊天记录，照着顾客的原话问。</li><li>检查回复：内容对不对、语气合不合适、该转人工的有没有转。</li></ol><h2 id="建议的测试清单" tabindex="-1">建议的测试清单 <a class="header-anchor" href="#建议的测试清单" aria-label="Permalink to &quot;建议的测试清单&quot;">​</a></h2><p>至少把这几类问题各测几条：</p><ul><li><strong>高频问题</strong>：发货时间、退换货政策、尺码推荐。</li><li><strong>商品细节</strong>：具体商品的参数、卖点，验证<a href="/aicare-docs/knowledge/product-learn">商品学习</a>和知识库的效果。</li><li><strong>关键词场景</strong>：配置过<a href="/aicare-docs/solution/keywords">关键词回复</a>的词，确认命中的是固定话术。</li><li><strong>该转人工的问题</strong>：投诉、改地址、议价，确认 AI 会发起转接而不是硬答。</li><li><strong>边界问题</strong>：和店铺无关的闲聊、故意刁难，看 AI 是否得体。</li></ul><h2 id="看测试结果" tabindex="-1">看测试结果 <a class="header-anchor" href="#看测试结果" aria-label="Permalink to &quot;看测试结果&quot;">​</a></h2><p>测试对话里能看到 AI 的回复过程：命中了哪个情景、引用了哪些知识库内容。回答不对时按这个顺序排查：</p><ol><li>引用了错的资料 → 修改知识库对应条目。</li><li>没引用资料 → 知识库缺内容，补充问答。</li><li>资料对但话术不好 → 调整 AI 设置里的回复设定。</li><li>命中了错误的情景 → 调整<a href="/aicare-docs/solution/triggers">触发规则</a>。</li></ol><p>改完再测，直到满意为止，然后回到店铺开启 AI 接待。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>测试会打扰真实顾客吗？</strong> 不会。测试完全在熠智 AI 内部进行，不连接电商平台。</p><p><strong>测试会扣客服回复点数吗？</strong> 不会。方案编辑器里的对话测试会标记为测试，不扣客服回复点数。</p><p><strong>测试和线上表现会一样吗？</strong> 方案、知识库和智能程度完全一致。线上多了平台消息形态（订单卡片、图片等），这部分靠<a href="/aicare-docs/solution/editor#特殊消息处理">特殊消息处理</a>配置。</p>',16)])])}const _=t(l,[["render",i]]);export{u as __pageData,_ as default};
